@IsTest private class CyclePhaseObservation {
 private static void run(String mode,Boolean input,Boolean scheduled){
  if(input)insert new Account(Name='cycle-input');
  Test.startTest();
  Id parent;
  if(scheduled)System.schedule('cycle-phase-continuation','0 0 0 1 1 ? 2099',new CyclePhaseBatch(mode));
  else parent=Database.executeBatch(new CyclePhaseBatch(mode));
  CyclePhaseBatch.snapshot('enq',parent);
  String error='';
  try{Test.stopTest();}catch(Exception e){error=e.getTypeName()+':'+e.getMessage();}
  CyclePhaseBatch.snapshot('99',parent);
  List<Object> rows=new List<Object>();
  for(Account row:[SELECT Description FROM Account WHERE Name LIKE 'cycle-phase-%' ORDER BY Name])rows.add(JSON.deserializeUntyped(row.Description));
  System.assertEquals('NATIVE_OBSERVATION',JSON.serialize(new List<Object>{mode,input,scheduled,error,rows}));
 }
 @IsTest static void plainEmpty(){run('NONE',false,false);}
 @IsTest static void guardedEmpty(){run('GUARDED',false,false);}
 @IsTest static void guardedOne(){run('GUARDED',true,false);}
 @IsTest static void finishScheduleOnly(){run('SCHEDULE_ONLY',false,false);}
 @IsTest static void finishAbortChild(){run('ABORT',false,false);}
 @IsTest static void finishKeepChild(){run('KEEP',false,false);}
 @IsTest static void directScheduleAbortChild(){run('ABORT',false,true);}
 @IsTest static void directScheduleKeepChild(){run('KEEP',false,true);}
}

