public class CyclePhaseBatch implements Database.Batchable<SObject>,Database.Stateful,Database.AllowsCallouts,Schedulable {
 private String mode; private Boolean child; private Id rootId;
 public CyclePhaseBatch(String value){mode=value;child=false;}
 public CyclePhaseBatch(String value,Id parent){mode=value;child=true;rootId=parent;}
 public Database.QueryLocator start(Database.BatchableContext context){
  if(rootId==null)rootId=context.getJobId();
  snapshot(child?'20':'00',rootId);
  return Database.getQueryLocator([SELECT Id FROM Account WHERE Name='cycle-input']);
 }
 public void execute(Database.BatchableContext context,List<SObject> scope){snapshot(child?'21':'01',rootId);}
 public void finish(Database.BatchableContext context){
  snapshot(child?'22':'02',rootId);
  Set<String> pending=new Set<String>{'Preparing','Processing','Queued','Holding'};
  Boolean permitted=mode!='GUARDED'||[SELECT COUNT() FROM AsyncApexJob WHERE ApexClass.Name='CyclePhaseBatch' AND JobType IN ('BatchApex','ScheduledApex') AND Status IN :pending]==0;
  if(!child&&mode!='NONE'&&permitted){
   Datetime nextTime=Datetime.now().addMinutes(15);
   String cron=nextTime.second()+' '+nextTime.minute()+' '+nextTime.hour()+' '+nextTime.day()+' '+nextTime.month()+' ? '+nextTime.year();
   System.schedule('cycle-phase-continuation',cron,new CyclePhaseBatch(mode,rootId));
  }
  if(!child)snapshot('03',rootId);
 }
 public void execute(SchedulableContext context){
  snapshot('10',rootId);
  if(mode=='ABORT'||mode=='GUARDED'){System.abortJob(context.getTriggerId());snapshot('11',rootId);}
  if(mode!='SCHEDULE_ONLY'){Database.executeBatch(new CyclePhaseBatch(mode,rootId),100);snapshot('12',rootId);}
 }
 public static void snapshot(String phase,Id root){
  List<String> jobs=new List<String>();
  for(AsyncApexJob job:[SELECT Id,JobType,Status,JobItemsProcessed,TotalJobItems,NumberOfErrors FROM AsyncApexJob WHERE ApexClass.Name='CyclePhaseBatch']){
   String kind=job.JobType=='BatchApex'?'B':(job.JobType=='BatchApexWorker'?'W':'S');
   Map<String,String> states=new Map<String,String>{'Queued'=>'Q','Preparing'=>'R','Processing'=>'P','Completed'=>'C','Aborted'=>'A','Failed'=>'F'};
   jobs.add(kind+':'+states.get(job.Status)+':'+(job.Id==root?'r':'o')+':'+job.JobItemsProcessed+'/'+job.TotalJobItems+'/'+job.NumberOfErrors);
  }
  jobs.sort();
  List<String> crons=new List<String>();
  for(CronTrigger cron:[SELECT State FROM CronTrigger WHERE CronJobDetail.Name='cycle-phase-continuation'])crons.add(cron.State);
  crons.sort();
  Set<String> pending=new Set<String>{'Preparing','Processing','Queued','Holding'};
  Integer selected=[SELECT COUNT() FROM AsyncApexJob WHERE ApexClass.Name='CyclePhaseBatch' AND JobType='BatchApex' AND Status IN :pending];
  insert new Account(Name='cycle-phase-'+phase,Description=JSON.serialize(new List<Object>{phase,jobs,crons,selected}));
 }
}

